Section Tail.
  Variables (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word)
            (F : bvmap 5 word) (fc : bv 32) (m : mem).
  Variables (lo size : Z) (d : depot).
  Variables (TSD CTX TH TOP BOT : Z) (T : list Z) (rest : list word).
  Variables (sb cnt mc : Z) (chunks : list Z) (j0 j1 j2 j3 : word).
  Let SO := bv_unsigned sp + -2128.
  (* [comment removed for export] *)
  Variables (rz needed c csz csz8 fl CA P cp AB U n id : Z).
  Hypothesis DEFS : ltac2:(zQ "h30!o4!ht2!hif!re!irc!ln4!lrf!mga!ml8!mm3!jt1!mmf!mnb!mo6!moc!mp2!mp8!mpe!lme@1$6@2$2@3$1$0?2rz@1$c?4size@2$2@3$1$0?6needed@2$3@2$b@2$f?4size+8+8?2rz@2$2@3$1$0?1c@1$9?6needed@2$2@3$1$0?3csz@1$a?1c@2$2@3$1$0?4csz8@2$e?3csz+8@2$2@3$1$0?2fl@2$h0?4size+hgg0@2$2@3$1$0?2CA@2$3?2TH+t0@2$2@3$1$0?1P@2$3?2CA@2$4+l0?1c@2$2@3$1$0?2cp@3$d$0Z?6chunks@2$2@3$1$0?2AB@2$3@2$3?2sb@2$4?1c@2$h2+2+i0@2$4?2cp+h0@2$2@3$1$0?1U@2$3?2AB?2rz@2$2@3$1$0?1n@1$h1@2$5$0?1T@3$1$0?2id@2$8?1d@1$7?1T").
  Let W : list ivl := (lo, (bv_unsigned sp)) :: (P, P + 4) :: (CA + 2576, CA + 2584) :: (AB, AB + csz) :: (sh AB, sh AB + csz8)
                      :: (TH + 2800, TH + 3169) :: depot_W d.
  Let W2 : list ivl := (lo, (bv_unsigned sp)) :: (P, P + 4) :: (CA + 2576, CA + 2584) :: (AB, AB + csz) :: (sh AB, sh AB + csz8)
                      :: (TH + 2800, TH + 3169) :: nil.
  Let POST := malloc_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m W lo size AB U rz csz P cnt mc TH id chunks
                          (d_put d (depot_hash T) n).
  Let AFR := aframe (Z_to_bv 64 (bv_unsigned sp + -2144)) (wz 0x69058) sp (wz size) (wz 0x90e00) (wz 1)
                    (Z_to_bv 64 (bv_unsigned sp + -2128)) (Z_to_bv 64 (bv_unsigned sp + -81)) s6 s7 s8 s9 s10 s11.

  Hypothesis LO : ltac2:(zQ "20!ih6!hgc@2$1@1$0?5HCEIL?2lo").  Hypothesis HI : ltac2:(zQ "40!h9!re!hgc!hs4@2$2@2$1?2lo+ps0@2$3@1$0#k0?2sp").
  Hypothesis SPA : ltac2:(zQ "60!ht2!h9!o4!lrf!ir3!hs4@1$3@3$0$2@2$4@2$5@1$1#k0?2sp+h0Z").
  Hypothesis SPT : ltac2:(zQ "60!h9!lrf!re!hgc!lme!hs4@1$1@2$3@2$2@2$5@1$0#k0?2sp+h0@2$4+2+if").
  Hypothesis SZ : ltac2:(zQ "30!hgc!hif!mq7@2$1@2$0+1?4size@2$0?6needed$2").
  Hypothesis TPR : ltac2:(zQ "70!h9!hgc!hs4!hif!mr3!lrf!re@1$5@2$3@2$1+mqiho8@2$2@1$0#k0?2tp@2$1@2$6@2$2@1$0#k0?2tp+hgg0$4").
  Hypothesis RNG : ltac2:(zQ "b0!hif!hgc!re!ih6!ht2!o4!mr3!jn7!lrf!mre!ir3@1$8@2$0@2$1+mqihj0?3TSD@2$0@2$1@2$2?3TSD+8$6@2$0@3$9?5HCEIL?3CTX+q0@2$0@2$1@2$2?3CTX+q0@1$3?5HCEIL@2$0@3$7?5HCEIL?2TH+hgg0@2$0@2$1@2$2?2TH+hgg0@1$3?5HCEIL@3$4$5@2$a?2TH+h0Z").
  Hypothesis PLC : ltac2:(zQ "60!re!hgc!ms6!hif!jtf!lrf@1$5@2$3@2$2@2$1@2$0?2TH+hgg0?2sb@2$1@2$0@2$0?2sb$4+hgg0?2TH@2$3@2$2@2$1@2$0?3CTX+q0?2sb@2$1@2$0@2$0?2sb$4+hgg0?3CTX@2$2@2$1@2$0?3CTX+q0?2TH@2$1@2$0?2TH+hgg0?3CTX").
  Hypothesis PLCD : ltac2:(zQ "a1!re!hgc!irc!hif!msc!mt4!ms6!mre!jtf!lrf&@2$0@1$4?1d@2$2+h0+hggg0@1$9@2$3@2$6@2$1@2$0?2TH+hgg0@1$4?1d@2$1~0?2TH@2$3@2$6@2$1@2$0?2TH+hgg0@1$5?1d@2$1@2$0@1$5?1d@2$2+8+ogg0?2TH@2$3@2$6@2$1@2$0@2$0?2sb$8+hgg0@1$4?1d@2$1~0?2sb@2$3@2$6@2$1@2$0@2$0?2sb$8+hgg0@1$5?1d@2$1@2$0@1$5?1d@2$2+8+ogg0?2sb@2$3@2$6@2$1@2$0?3CTX+q0@1$4?1d@2$1~0?3CTX@2$3@2$6@2$1@2$0?3CTX+q0@1$5?1d@2$1@2$0@1$5?1d@2$2+8+ogg0?3CTX@2$3@3$7?5HCEIL@1$4?1d@2$2+h0+hggg0@3$7?5HCEIL@1$5?1d@2$2+8+ogg0").
  Let PLACED : Prop := ((TH + 4096 <= sb \/ sb + kSpaceSize + 4096 <= TH) /\ (CTX + 160 <= sb \/ sb + kSpaceSize + 4096 <= CTX)
                /\ (CTX + 160 <= TH \/ TH + 4096 <= CTX))
               /\ ((TH + 4096 <= d_nb d \/ d_nb d + 16 * 65536 <= TH) /\ (TH + 4096 <= d_sb d \/ d_sb d + 8 * 32768 <= TH)
                /\ (sb + kSpaceSize + 4096 <= d_nb d \/ d_nb d + 16 * 65536 <= sb) /\ (sb + kSpaceSize + 4096 <= d_sb d \/ d_sb d + 8 * 32768 <= sb)
                /\ (CTX + 160 <= d_nb d \/ d_nb d + 16 * 65536 <= CTX) /\ (CTX + 160 <= d_sb d \/ d_sb d + 8 * 32768 <= CTX)
                /\ aapp (d_nb d) (16 * 65536) /\ aapp (d_sb d) (8 * 32768)).
  Hypothesis SBR : ltac2:(zQ "a0!hif!hgc!ht2!o4!lrf!mtc!ih6!jtf!re!ir3@1$4@2$0@2$1$5?2sb@2$0@2$1@2$8?2sb$7@1$6?5HCEIL@3$2$3@2$9?2sb+hggg0Z").
  Hypothesis CNT : ltac2:(zQ "30!o4!ht2!jud@3$1$0?3cnt@2$2$0?6chunks"). Hypothesis HIT : ltac2:(zQ "20!hgc!hif@2$1@2$0+1?3cnt@2$0?3cnt+h0").
  Hypothesis CPS : ltac2:(zQ "60!o4!hif!iu7!hgc!iqe!lme@3$2$0\2cp$0@2$1@2$3Z^1@2$4^1@2$5+2+i0?6chunks").
  Hypothesis ABR : ltac2:(zQ "50!re!hgc!hif!lrf!jtf@1$3@2$2@2$1?2sb?2AB@2$1@2$0?2AB?3csz@2$0?2sb$4").
  Hypothesis TBR : ltac2:(zQ "50!hif!hgc!lrf!iqe!lme@1$2@2$0@2$0@2$1+hgg0?3TOP@2$1?3TOP@2$4+2+if@2$0@2$1Z?3BOT@2$3?3BOT?3TOP").
  Hypothesis DCAP : ltac2:(zQ "60!re!hif!mu6!mv2!hgc!iqe@2$1@2$5@2$0@1$3?1d+1+hggg0@2$4@2$0@1$2?1d+hf+ogg0").
  Hypothesis DLO : ltac2:(zQ "60!re!hgc!irc!hif!msc!mt4@2$3@2$1@2$0@1$4?1d@2$2+h0+hggg0?2lo@2$1@2$0@1$5?1d@2$2+8+ogg0?2lo").
  (* [comment removed for export] *)
  Hypothesis NRT : ltac2:(zQ "40!ln4!ngf!o4!hif@2$3@2$1N1@2$0$2?1T@2$1@2$0$2?1TNhe"). Hypothesis LR : ltac2:(zQ "70!ln4!nh5!ht2!nid!h9!o4!jc@3$2$1@2$0@1$6@1$4#k0?4rest@2$3Nvf@2$0$5?1T"). Hypothesis TRNG : ltac2:(zQ "60!o4!hif!iu7!hgc!iqe!lme@3$2$0\1x$0@2$1@2$3Z^1@2$4^1@2$5+2+k0?1T").

  Ltac prepI :=
    pose proof DEFS as DEFS'; destruct DEFS' as [(DRZ & DNEED & DC & DCSZ & DC8 & DFL & DCA & DP & DCP & DAB & DU & DN & DID)];
    pose proof (bv_unsigned_in_range _ sp) as SPR; change (bv_modulus 64) with (2^64)%Z in SPR;
    assert (BND : aceil <= lo /\ 6955312 <= TSD /\ TSD + 8 <= 7430144 /\ 7430144 <= CTX /\ CTX + 160 <= aceil
               /\ 4096 <= TH /\ TH + 4096 <= aceil /\ 17594333495296 <= sb /\ sb + 137438953472 <= aceil
               /\ sb <= AB /\ AB + csz <= sb + 137438953472 /\ 6955400 <= bv_unsigned tp /\ bv_unsigned tp + 4096 <= 7430144
               /\ bv_unsigned sp + 16 <= 140737488355328 /\ 4096 <= TOP /\ TOP <= 140737488355328 /\ 0 <= BOT /\ BOT < TOP)
      by (clear - LO RNG SBR ABR TPR SPT TBR; try acb; destruct RNG as [RNG']; destruct SBR as [SBR']; destruct ABR as [ABR']; destruct TPR as [TPR'];
          destruct SPT as [SPT']; destruct TBR as [TBR']; unfold akobj, alow1, aapp, aapp_lo, aapp_hi, AIMG_LO, ALOWSH_LO in *; unfold AHI_LO, kSpaceSize, AIMG_TOP in *;
          acb; change (2^47)%Z with 140737488355328%Z in SPT', TBR'; lia);
        region_sides; name_bands;
    assert (HC : 1 <= c < 32)
      by (clear - SZ DC DNEED DRZ; try acb; subst c needed rz; apply class_id_range; unfold kMaxSize in SZ; pose proof (rz_size_facts size); unfold round_up in *;
          Z.div_mod_to_equations; lia);
    assert (CSZ : 32 <= csz <= 65536 /\ needed <= csz)
      by (clear - SZ HC DCSZ DNEED DRZ DC; try acb; pose proof (class_size_table_facts c ltac:(hci; lia)); subst csz;
          pose proof (class_size_ge needed ltac:(hci; unfold kMaxSize in SZ; subst needed rz; pose proof (rz_size_facts size); unfold round_up in *;
                                             Z.div_mod_to_equations; lia)); subst c; lia);
    assert (RZB : 16 <= rz <= 2048 /\ size + rz <= needed /\ 8 + rz <= needed /\ needed < size + rz + 8)
      by (clear - SZ DNEED DRZ; try acb; subst needed rz; pose proof (rz_size_facts size); unfold round_up; Z.div_mod_to_equations; lia);
    assert (ALN : exists thq sbq rzk ck nk, TH = 16 * thq /\ sb = 65536 * sbq /\ rz = 16 * rzk /\ csz = 32 * ck /\ needed - rz = 8 * nk)
      by (clear - RNG SBR HC DCSZ DNEED DRZ; try acb; destruct RNG as [RNG']; destruct SBR as [SBR']; pose proof (rz_size_facts size);
          pose proof (class_size_table_facts c ltac:(hci; lia)); subst csz needed rz; unfold round_up;
          exists (TH / 16), (sb / 65536), (rz_size size / 16), (class_size c / 32), ((size `max` 8 + 8 - 1) / 8);
          Z.div_mod_to_equations; lia);
    destruct ALN as (thq & sbq & rzk & ck & nk & ALN);
    assert (SPQ : exists spq, bv_unsigned sp = 16 * spq) by (clear - SPA; try acb; destruct SPA as [SPA']; exists (bv_unsigned sp / 16); Z.div_mod_to_equations; lia);
    destruct SPQ as [spq SPQ];
    assert (PLCh : hidden PLACED) by (destruct PLC as [PLC']; destruct PLCD as [PLCD']; exact (Hide _ (conj PLC' PLCD')));
    assert (EQS : U = AB + rz /\ P = TH + 208 + 80 * c /\ AB = sb + c * 2 ^ 32 + cp * 16 /\ n = Z.of_nat (length T) /\ CA = TH + 208)
      by (rewrite DU, DP, DAB, DN, DCA; repeat split; reflexivity);
    assert (EQh : hidden (c = class_id needed /\ csz = class_size c /\ rz = rz_size size /\ needed = round_up (Z.max size 8) 8 + rz
                       /\ cp = hd 0 chunks /\ id = d_putid d (depot_hash T) /\ csz8 = csz / 8)) by (constructor; repeat split; first [assumption | reflexivity]);
    assert (C8F : 8 * csz8 = csz) by (clear - ALN DC8; try acb; subst csz8; Z.div_mod_to_equations; lia);
    assert (PB : TH + 288 <= P /\ P + 80 <= TH + 2768) by (clear - HC EQS; try acb; lia);
    assert (SHR : 2201439137792 <= sh AB /\ sh AB + csz8 <= 17594333495296) by (clear - BND C8F; try acb; unfold sh, ASHADOW_BASE; Z.div_mod_to_equations; lia);
    assert (NR : 1 <= n <= 30) by (rewrite DN; clear - NRT; try acb; lia);
    clear DRZ DNEED DC DCSZ DC8 DFL DCA DP DCP DAB DU DN DID.

  Ltac plia :=
    first [ lia
          | match goal with H : hidden PLACED |- _ =>
              let P := fresh "PLu" in pose proof H as P; destruct P as [P]; unfold PLACED, kSpaceSize, AHI_LO in P;
              let A1 := fresh "PA" in let A2 := fresh "PA" in let A3 := fresh "PA" in
              let B1 := fresh "PB" in let B2 := fresh "PB" in let B3 := fresh "PB" in let B4 := fresh "PB" in
              let B5 := fresh "PB" in let B6 := fresh "PB" in let B7 := fresh "PB" in let B8 := fresh "PB" in
              destruct P as [[A1 [A2 A3]] [B1 [B2 [B3 [B4 [B5 [B6 [B7 B8]]]]]]]];
              first [ clear A2 A3 B1 B2 B3 B4 B5 B6; lia
                    | clear A1 A3 B1 B2 B3 B4 B5 B6; lia
                    | clear A1 A2 B1 B2 B3 B4 B5 B6; lia
                    | clear A1 A2 A3 B2 B3 B4 B5 B6; lia
                    | clear A1 A2 A3 B1 B3 B4 B5 B6; lia
                    | clear A1 A2 A3 B1 B2 B4 B5 B6; lia
                    | clear A1 A2 A3 B1 B2 B3 B5 B6; lia
                    | clear A1 A2 A3 B1 B2 B3 B4 B6; lia
                    | clear A1 A2 A3 B1 B2 B3 B4 B5; lia ]
            end ].
  Ltac solve_depot_avoid ::=
    unfold depot_avoid, avoids; rewrite ?d_nb_put, ?d_sb_put; cbn [fst snd];
    repeat split;
    repeat (first [apply Forall_nil | apply Forall_cons; [cbn beta iota delta [fst snd]; plia |]]).
  (* [comment removed for export] *)
  Ltac dlia := lazymatch goal with |- _ <= _ \/ _ <= _ => lia | |- _ \/ _ => first [ left; dlia | right; dlia ] | |- _ /\ _ => split; dlia | |- _ => lia end.
  Ltac splia := lazymatch goal with |- _ /\ _ => split; splia | |- _ => plia end.
  Ltac slia ::= first [ exact I | dlia | splia ].

  Theorem malloc_from_refill : forall (x5 x6 x7 x11 x12 x13 x14 x15 x16 x17 x28 x29 x30 x31 : word) (jk j8 : list byte),
    AENV tp TSD CTX TH sb SO T rest m -> mem_inv asegs m ->
    stk asegs m lo (bv_unsigned sp + -2320) ->
    (* [comment removed for export] *)
    rw_cells asegs m (bv_unsigned sp + -2320) [C8 (wz rz); C8 (wz needed); C8 (wz 8); C8 (wz size); C8 (wz 1); C8 (wz 0x69328)] ->
    AFR m j8 ->
    rw_cells asegs m (bv_unsigned sp + -2144) [C8 sp; C8 (wz 0x90e6c)] ->
    rw_cells asegs m (bv_unsigned sp + -72) [C8 sp] ->
    rw_cells asegs m (bv_unsigned sp + -64) [CB 8 jk; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra] ->
    (* [comment removed for export] *)
    rw_cells asegs m P [C4 (wz cnt); C4 (wz mc)] -> rw_cells asegs m (P + 8) [C8 (wz csz)] -> u32arr asegs m (P + 16) (wlist (rev chunks)) ->
    stk asegs m (P + 16 + 4 * cnt) (P + 80) -> rw_cells asegs m (TH + 208 + 2560) [C8 j0; C8 j1; C8 j2; C8 j3] ->
